package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
class JdbcPointLedgerTest extends JdbcCouponInventoryTest {
 PointLedger ledger;PointTaskPolicies policies;ArchiveStructuredService archives;
 @BeforeEach void ledger(){jdbc.execute("DROP TRIGGER IF EXISTS fail_point_ledger");for(String t:List.of("point_checkin_request","point_verified_entry","point_verified_account","point_task_event","point_task_policy","point_flow","archive_structured_detail","vehicle_archive","vehicle"))jdbc.update("DELETE FROM "+t);jdbc.update("UPDATE operator_account SET can_points=1 WHERE id=1");var tx=new DataSourceTransactionManager(jdbc.getDataSource());policies=new PointTaskPolicies(db,new OperatorIdentity(jdbc,null,tx));ledger=new PointLedger(db,policies,"test-app",true,true);archives=new ArchiveStructuredService(jdbc,db.writes,json,tx,ledger);jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());jdbc.update("INSERT INTO vehicle(id,user_id,plate_no) VALUES(901,1,'synthetic-points')");jdbc.update("INSERT INTO vehicle_archive(id,vehicle_id,archive_type,input_type,content,recorded_at) VALUES(901,901,1,1,'{}',CURRENT_DATE)");}
 long policy(String type){var b=json.createObjectNode().put("task_type",type).put("points",7).put("source_note","用户确认合成规则").put("valid_from",clock.value.minusSeconds(60).toString()).put("valid_to",clock.value.plusSeconds(3*86400).toString());long id=policies.create(operator,key(),b).path("data").path("id").asLong();policies.status(operator,id,key(),statusBody(1,"PUBLISHED"));return id;}
 String day(){return clock.value.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().toString();}
 ObjectNode check(long p){return json.createObjectNode().put("day",day()).put("policy_id",p).put("policy_revision",2);}
 long checkin(long p){return ledger.checkin(owner,key(),check(p)).path("data").path("event_id").asLong();}
 ObjectNode fields(){var n=json.createObjectNode().put("owner_confirmed",true).put("source_reference","本人核对保养单").put("source_checked_on",LocalDate.now(ZoneId.of("Asia/Shanghai")).toString()).put("provider_name","合成维修店").put("performed_mileage",100).put("service_date",LocalDate.now(ZoneId.of("Asia/Shanghai")).toString());n.putArray("service_items").add("换油");return n;}
 @Test void unknownIdentityAndDisabledOrUnconfiguredTasksNeverCreateFormalPoints(){long p=policy("CHECK_IN");for(String source:List.of("TEST","UNKNOWN")){jdbc.update("UPDATE auth_session SET point_identity_source=? WHERE id=?",source,owner.session());assertEquals(409,code(()->checkin(p)));}jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());assertEquals(409,code(()->new PointLedger(db,policies,"test-app",false,true).checkin(owner,key(),check(p))));assertEquals(0,count("point_task_event"));assertEquals(0,count("point_verified_entry"));assertEquals(0,count("point_verified_account"));}
 @Test void sessionEvidenceIsAppScopedAndCannotPromoteTestOrOtherSessions(){jdbc.update("UPDATE auth_session SET point_identity_source='UNKNOWN' WHERE id=?",owner.session());ledger.recordIdentity(owner.session(),2,"test-app",true);assertEquals("UNKNOWN",jdbc.queryForObject("SELECT point_identity_source FROM auth_session WHERE id=?",String.class,owner.session()));ledger.recordIdentity(owner.session(),1,"other-app",true);assertEquals("UNKNOWN",jdbc.queryForObject("SELECT point_identity_source FROM auth_session WHERE id=?",String.class,owner.session()));ledger.recordIdentity(owner.session(),1,"test-app",true);assertEquals("VERIFIED_WECHAT",jdbc.queryForObject("SELECT point_identity_source FROM auth_session WHERE id=?",String.class,owner.session()));jdbc.update("UPDATE auth_session SET point_identity_source='TEST' WHERE id=?",owner.session());ledger.recordIdentity(owner.session(),1,"test-app",true);assertEquals("TEST",jdbc.queryForObject("SELECT point_identity_source FROM auth_session WHERE id=?",String.class,owner.session()));}
 @Test void checkinCaptureAndCreditAreDistinctAtomicFactsWithNoLegacyImport(){jdbc.update("UPDATE user SET point_balance=1280 WHERE id=1");long id=checkin(policy("CHECK_IN"));assertEquals(0,count("point_verified_entry"));assertEquals(0L,ledger.overview(owner).get("balance"));assertEquals("REVIEW_REQUIRED",ledger.overview(owner).get("legacy_state"));assertTrue(ledger.credit(id));assertFalse(ledger.credit(id));assertEquals(7L,ledger.overview(owner).get("balance"));assertEquals(1280,jdbc.queryForObject("SELECT point_balance FROM user WHERE id=1",Integer.class));assertEquals(0,count("point_flow"));assertEquals(1,count("point_verified_entry"));assertEquals("system",jdbc.queryForObject("SELECT actor_type FROM audit_log WHERE action='POINT_TASK_CREDIT'",String.class));assertEquals(0L,jdbc.queryForObject("SELECT actor_id FROM audit_log WHERE action='POINT_TASK_CREDIT'",Long.class));assertEquals(1L,ledger.flow(owner,1).get("total"));assertEquals(0L,ledger.flow(peer,1).get("total"));}
 @Test void permanentKeysAndFixedDayPreventCrossDayUnknownRequestsFromSigningInAgain(){clock.value=LocalDate.now(ZoneId.of("Asia/Shanghai")).atTime(15,59,59).toInstant(ZoneOffset.UTC);long p=policy("CHECK_IN");String k=key();var b=check(p);var one=ledger.checkin(owner,k,b);long id=one.path("data").path("event_id").asLong();assertEquals(id,checkin(p));assertEquals(1,count("point_task_event"));ledger.credit(id);clock.value=clock.value.plusSeconds(1);jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(one.path("data"),ledger.checkin(owner,k,b).path("data"));assertEquals(400,code(()->ledger.checkin(owner,k,check(p))));assertEquals(409,code(()->ledger.checkin(owner,key(),b)));assertNotEquals(id,checkin(p));assertEquals(2,count("point_task_event"));}
 @Test void checkinBindsCurrentPolicyAndEndTime(){long p=policy("CHECK_IN");assertEquals(409,code(()->ledger.checkin(owner,key(),check(p).put("policy_revision",1))));clock.value=clock.value.plusSeconds(3*86400);assertEquals(409,code(()->checkin(p)));assertEquals(0,count("point_task_event"));}
 @Test void manualCompletionIsCapturedInsideSourceTransactionAndNeverRescansHistory(){policy("ARCHIVE_FIRST_COMPLETE");archives.save(owner,901,key(),new ArchiveStructuredInput(0,json.createObjectNode().put("provider_name","不完整")));assertEquals(0,count("point_task_event"));archives.save(owner,901,key(),new ArchiveStructuredInput(1,fields()));assertEquals(1,count("point_task_event"));archives.save(owner,901,key(),new ArchiveStructuredInput(2,fields()));assertEquals(1,count("point_task_event"));ledger.recover();assertEquals(7L,ledger.overview(owner).get("balance"));assertFalse(jdbc.queryForObject("SELECT source_hash FROM point_task_event",String.class).contains("本人"));assertEquals(404,code(()->archives.save(peer,901,key(),new ArchiveStructuredInput(0,fields()))));}
 @Test void oldCompleteRecordsUnconfirmedAndAutomaticArchivesDoNotBecomeNewTasks(){policy("ARCHIVE_FIRST_COMPLETE");jdbc.update("INSERT INTO archive_structured_detail(user_id,vehicle_id,archive_id,archive_type,fields_json,revision) VALUES(1,901,901,1,?,1)",fields().toString());archives.save(owner,901,key(),new ArchiveStructuredInput(1,fields()));assertEquals(0,count("point_task_event"));jdbc.update("UPDATE vehicle_archive SET input_type=4 WHERE id=901");db.transactions.executeWithoutResult(tx->ledger.archiveCompleted(owner,901));assertEquals(0,count("point_task_event"));assertFalse(PointLedger.completeManual(1,fields().put("owner_confirmed",false)));assertFalse(PointLedger.completeManual(3,fields()));}
 @Test void sourceAndEventRollBackTogetherOnCaptureAuditFailure(){policy("ARCHIVE_FIRST_COMPLETE");jdbc.execute("CREATE TRIGGER fail_point_ledger BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->archives.save(owner,901,key(),new ArchiveStructuredInput(0,fields()))));assertEquals(0,count("archive_structured_detail"));assertEquals(0,count("point_task_event"));}
 @Test void aiRequiresOfficialSuccessfulSourceAndRevalidatesAfterIo(){policy("AI_FIRST_SUCCESS");ledger.aiSucceeded(owner,"替身答复","fake",false);ledger.aiSucceeded(owner," ","real",true);new PointLedger(db,policies,"test-app",true,false).aiSucceeded(owner,"答复","model",true);assertEquals(0,count("point_task_event"));ledger.aiSucceeded(owner,"真实成功答复","model",true);ledger.aiSucceeded(owner,"另一次答复","model",true);assertEquals(1,count("point_task_event"));assertFalse(jdbc.queryForList("SELECT * FROM point_task_event").toString().contains("真实成功答复"));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->ledger.aiSucceeded(owner,"不得接收","model",true)));}
 @Test void recoveryHonorsFrozenTermsAndPausesDisabledAccounts(){long p=policy("CHECK_IN"),id=checkin(p);policies.status(operator,p,key(),statusBody(2,"STOPPED"));var pending=(java.util.Map<?,?>)((java.util.List<?>)ledger.overview(owner).get("tasks")).get(0);assertEquals(7,((com.fasterxml.jackson.databind.JsonNode)pending.get("policy")).path("points").asInt());assertEquals("PENDING",pending.get("state"));jdbc.update("UPDATE user SET status=0 WHERE id=1");ledger.recover();assertEquals(0,count("point_verified_entry"));jdbc.update("UPDATE user SET status=1 WHERE id=1");new PointLedger(db,policies,"test-app",true,true).recover();assertEquals(1,count("point_verified_entry"));assertEquals(7L,ledger.overview(owner).get("balance"));}
 @Test void ledgerAuditFailureRollsBackBalanceEntryAndCompletionThenRecovers(){long id=checkin(policy("CHECK_IN"));jdbc.execute("CREATE TRIGGER fail_point_ledger BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");ledger.recover();assertEquals(0,count("point_verified_entry"));assertEquals(0,count("point_verified_account"));assertEquals("PENDING",jdbc.queryForObject("SELECT status FROM point_task_event WHERE id=?",String.class,id));assertEquals(1,jdbc.queryForObject("SELECT attempts FROM point_task_event WHERE id=?",Integer.class,id));jdbc.execute("DROP TRIGGER fail_point_ledger");clock.value=clock.value.plusSeconds(31);ledger.recover();assertEquals(7L,ledger.overview(owner).get("balance"));}
 @Test void twoConsumersAndConcurrentDifferentKeysCreditExactlyOnce()throws Exception{long p=policy("CHECK_IN");var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return checkin(p);});var b=pool.submit(()->{start.await();return checkin(p);});start.countDown();long id=a.get(30,TimeUnit.SECONDS);assertEquals(id,b.get(30,TimeUnit.SECONDS));var c=pool.submit(()->ledger.credit(id));var d=pool.submit(()->ledger.credit(id));assertNotEquals(c.get(30,TimeUnit.SECONDS),d.get(30,TimeUnit.SECONDS));assertEquals(1,count("point_verified_entry"));assertEquals(7L,ledger.overview(owner).get("balance"));}finally{pool.shutdownNow();}}
 @Test void lifetimeTaskDoesNotRestartWithPolicyVersionOrAnotherDay(){long p=policy("AI_FIRST_SUCCESS");ledger.aiSucceeded(owner,"一次","model",true);policies.status(operator,p,key(),statusBody(2,"STOPPED"));policy("AI_FIRST_SUCCESS");clock.value=clock.value.plusSeconds(86400);ledger.aiSucceeded(owner,"另一天","model",true);ledger.recover();assertEquals(1,count("point_task_event"));assertEquals(7L,ledger.overview(owner).get("balance"));}
 @Test void policyLockWaitRechecksDeadlineBeforeCapturing()throws Exception{long p=policy("CHECK_IN");jdbc.update("UPDATE point_task_policy SET valid_to=? WHERE id=?",ReservationStore.time(clock.value.plusSeconds(60)),p);var b=check(p);var pool=Executors.newSingleThreadExecutor();try(var c=jdbc.getDataSource().getConnection()){c.setAutoCommit(false);try(var q=c.createStatement()){q.executeQuery("SELECT id FROM point_task_policy WHERE id="+p+" FOR UPDATE");}var future=pool.submit(()->{try{ledger.checkin(owner,key(),b);return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var diagnostics=new org.springframework.jdbc.core.JdbcTemplate(new org.springframework.jdbc.datasource.DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword()));boolean waiting=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<deadline){if(diagnostics.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("point_task_policy"))){waiting=true;break;}Thread.sleep(100);}assertTrue(waiting,"observe the actual policy lock wait");clock.value=clock.value.plusSeconds(60);c.commit();assertEquals(409,future.get(30,TimeUnit.SECONDS));assertEquals(0,count("point_task_event"));}finally{pool.shutdownNow();}}
 @Test void forgedInputCannotSupplyIdentityBalanceOrNewTaskType(){long p=policy("CHECK_IN");for(String raw:List.of(check(p).put("eligible",true).toString(),check(p).put("points",100).toString(),check(p).put("day","2026-02-30").toString(),check(p)+"{}"))assertThrows(Exception.class,()->PointLedger.checkinInput(raw));assertThrows(Exception.class,()->ledger.flow(owner,0));}
}
